<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
type Assignment = { AgencyPositionID:number; AgencyID:number; AgencyName:string; PositionID:number; PositionName:string; Description:string|null; AssignmentStatus:'Active'|'Inactive' }
type Agency = { AgencyID:number; AgencyName:string; Status:string }; type Position = { PositionID:number; PositionName:string }
const items=ref<Assignment[]>([]), agencies=ref<Agency[]>([]), positions=ref<Position[]>([]), searchInput=ref(''), search=ref(''), agencyFilter=ref(''), positionFilter=ref(''), loading=ref(true), busy=ref(false), error=ref(''), modalOpen=ref(false), editing=ref<Assignment|null>(null)
const form=ref({AgencyID:'',PositionID:'',PositionName:'',Description:'',Status:'Active'})
const filteredItems=computed(()=>{const term=search.value.trim().toLowerCase();return items.value.filter(i=>(!agencyFilter.value||i.AgencyID===Number(agencyFilter.value))&&(!positionFilter.value||i.PositionID===Number(positionFilter.value))&&(!term||[i.AgencyName,i.PositionName,i.Description,i.AssignmentStatus].filter(Boolean).join(' ').toLowerCase().includes(term)))})
function resetForm(item:Assignment|null=null){editing.value=item;form.value={AgencyID:item?String(item.AgencyID):'',PositionID:'',PositionName:item?.PositionName||'',Description:item?.Description||'',Status:item?.AssignmentStatus||'Active'};error.value=''}
async function load(){loading.value=true;try{const r:any=await $fetch('/api/organization/positions');items.value=r.items||[];agencies.value=r.agencies||[];positions.value=r.positions||[]}catch(cause:any){error.value=cause.data?.statusMessage||'Unable to load position assignments.'}finally{loading.value=false}}
function add(){resetForm();modalOpen.value=true}; function edit(item:Assignment){resetForm(item);modalOpen.value=true}; function runSearch(){search.value=searchInput.value}
async function save(){busy.value=true;error.value='';try{const body=editing.value?{id:editing.value.PositionID,agencyPositionId:editing.value.AgencyPositionID,...form.value}:form.value;await $fetch('/api/organization/positions',{method:editing.value?'PUT':'POST',body});modalOpen.value=false;await load()}catch(cause:any){error.value=cause.data?.statusMessage||'Unable to save position assignment.'}finally{busy.value=false}}
async function deactivate(item:Assignment){if(!confirm(`Mark ${item.PositionName} at ${item.AgencyName} as inactive?`))return;try{await $fetch('/api/organization/positions',{method:'DELETE',body:{agencyPositionId:item.AgencyPositionID}});await load()}catch(cause:any){error.value=cause.data?.statusMessage||'Unable to deactivate position assignment.'}}
onMounted(load)
</script>
<template><main class="positions-page"><header><div><p>ORGANIZATION</p><h1>Positions</h1><span>Assign every position to the agency where it is available.</span></div><button class="primary" @click="add">+ Add position</button></header><p v-if="error" class="error" role="alert">{{ error }}</p><section class="filters"><label class="search"><span>Search</span><input v-model="searchInput" type="search" placeholder="Agency, position, or description" @keyup.enter="runSearch"><button type="button" @click="runSearch">Search</button></label><label><span>Agency</span><select v-model="agencyFilter"><option value="">All Agencies</option><option v-for="a in agencies" :key="a.AgencyID" :value="a.AgencyID">{{ a.AgencyName }}</option></select></label><label><span>Position</span><select v-model="positionFilter"><option value="">All Positions</option><option v-for="p in positions" :key="p.PositionID" :value="p.PositionID">{{ p.PositionName }}</option></select></label></section><div class="table-wrap"><table><thead><tr><th>Agency</th><th>Position</th><th>Description</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="5">Loading…</td></tr><tr v-else-if="!filteredItems.length"><td colspan="5">No position assignments found.</td></tr><tr v-for="item in filteredItems" :key="item.AgencyPositionID"><td>{{ item.AgencyName }}</td><td>{{ item.PositionName }}</td><td>{{ item.Description||'—' }}</td><td><span class="status" :class="`status--${item.AssignmentStatus.toLowerCase()}`">{{ item.AssignmentStatus }}</span></td><td class="actions"><button @click="edit(item)">Edit</button><button :disabled="item.AssignmentStatus==='Inactive'" @click="deactivate(item)">Deactivate</button></td></tr></tbody></table></div><Teleport to="body"><div v-if="modalOpen" class="backdrop" @click.self="!busy&&(modalOpen=false)"><form class="modal" @submit.prevent="save"><button type="button" class="close" :disabled="busy" @click="modalOpen=false">×</button><h2>{{ editing?'Edit position assignment':'Add position' }}</h2><label>Agency<select v-model="form.AgencyID" required><option value="">Select agency</option><option v-for="a in agencies" :key="a.AgencyID" :value="a.AgencyID" :disabled="a.Status==='Inactive'">{{ a.AgencyName }}{{ a.Status==='Inactive'?' (Inactive)':'' }}</option></select></label><label v-if="!editing">Existing position (optional)<select v-model="form.PositionID"><option value="">Create a new position</option><option v-for="p in positions" :key="p.PositionID" :value="p.PositionID">{{ p.PositionName }}</option></select></label><template v-if="editing||!form.PositionID"><label>Position name<input v-model="form.PositionName" required></label><label>Description<textarea v-model="form.Description" /></label></template><label>Status<select v-model="form.Status"><option>Active</option><option>Inactive</option></select></label><p v-if="error" class="error">{{ error }}</p><footer><button type="button" @click="modalOpen=false">Cancel</button><button class="primary" :disabled="busy">{{ busy?'Saving…':'Save' }}</button></footer></form></div></Teleport></main></template>
<style scoped>
.positions-page{padding:32px;max-width:1200px;margin:auto;color:#172033;font-family:Inter,system-ui,sans-serif}header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}header p{font-size:.75rem;font-weight:800;letter-spacing:.08em;color:#5271a5;margin:0}h1{margin:3px 0;font-size:1.7rem}header span{color:#64748b;font-size:.9rem}.primary{border:0;border-radius:8px;background:#2563eb;color:#fff;font-weight:700;padding:10px 15px;cursor:pointer}.filters{display:flex;gap:14px;align-items:end;padding:16px;margin-bottom:18px;background:#f8fafc;border:1px solid #dfe5ef;border-radius:10px}.filters label,.modal label{display:grid;gap:6px;min-width:180px;color:#475569;font-size:.76rem;font-weight:700}.filters .search{flex:1;min-width:280px;grid-template-columns:1fr auto}.search span{grid-column:1/-1}.filters input,.filters select,.modal input,.modal select,.modal textarea{box-sizing:border-box;width:100%;min-height:40px;border:1px solid #cfd8e6;border-radius:7px;padding:9px;font:inherit;color:#172033}.search button,.actions button,footer button{border:1px solid #cfd8e6;background:#fff;border-radius:6px;padding:6px 10px;cursor:pointer}.table-wrap{overflow:auto;border:1px solid #dfe5ef;border-radius:10px;background:#fff}table{width:100%;border-collapse:collapse}th,td{padding:13px 14px;text-align:left;border-bottom:1px solid #edf1f6;font-size:.88rem;white-space:nowrap}th{background:#f8fafc;color:#526174;font-size:.75rem;text-transform:uppercase;letter-spacing:.04em}.actions{display:flex;gap:8px}.actions button:disabled{opacity:.45;cursor:not-allowed}.status{padding:3px 8px;border-radius:999px;font-size:.74rem;font-weight:700}.status--active{background:#dcfce7;color:#166534}.status--inactive{background:#fee2e2;color:#991b1b}.error{color:#b42318;margin:0 0 14px}.backdrop{position:fixed;inset:0;z-index:300;background:rgba(15,23,42,.58);display:grid;place-items:center;padding:16px}.modal{position:relative;width:min(100%,520px);max-height:90vh;overflow:auto;background:#fff;border-radius:12px;padding:26px;display:grid;gap:13px}.modal h2{margin:0 0 4px}.modal textarea{min-height:80px;resize:vertical}.modal footer{display:flex;justify-content:flex-end;gap:10px;margin-top:6px}.close{position:absolute;right:12px;top:10px;border:0;background:transparent;font-size:1.5rem;cursor:pointer}@media(max-width:720px){.positions-page{padding:20px}header{align-items:flex-start}.filters{align-items:stretch;flex-direction:column}.filters label,.filters .search{min-width:0}}
</style>
